			MDBVal key = MDBVal.malloc(stack).mv_data(stack.bytes((byte) 1));
			MDBVal value = MDBVal.malloc(stack).mv_data(stack.bytes((byte) 42));
			IntBuffer dbi = stack.mallocInt(1);
